def prime_factorization(n):
    factors = {}
    d = 2
    temp = n
    while d * d <= temp:
        while temp % d == 0:
            factors[d] = factors.get(d, 0) + 1
            temp //= d
        d += 1
    if temp > 1:
        factors[temp] = factors.get(temp, 0) + 1
    return factors

def tau(n):
    if n == 1:
        return 1
    factors = prime_factorization(n)
    tau_n = 1
    for exponent in factors.values():
        tau_n *= (exponent + 1)
    return tau_n

results = []
for k in range(1, 11):
    N = 2 * (k**3)
    tau_N = tau(N)
    target = 2 * k
    results.append((k, tau_N, target, tau_N == target))

print("k | tau(2k^3) | 2k | Equal?")
print("-" * 35)
for k, tau_N, target, equal in results:
    print(f"{k} | {tau_N}         | {target} | {equal}")
